<?php defined('BASEPATH') OR exit('No direct script access allowed'); ?>
<section class="py-4 border-bottom bg-light"><div class="container"><h1 class="h3 mb-1">Addresses</h1><p class="text-muted mb-0">Manage shipping and billing addresses.</p></div></section>
<section class="py-5"><div class="container"><div class="row g-4">
	<div class="col-lg-5"><form method="post" action="<?php echo site_url('account/addresses/save'); ?>" class="card"><input type="hidden" name="<?php echo html_escape($this->security->get_csrf_token_name()); ?>" value="<?php echo html_escape($this->security->get_csrf_hash()); ?>"><div class="card-body"><h2 class="h5 mb-3">Add Address</h2><div class="row g-2"><div class="col-6"><input class="form-control" name="first_name" placeholder="First name" required></div><div class="col-6"><input class="form-control" name="last_name" placeholder="Last name"></div><div class="col-12"><input class="form-control" name="phone" placeholder="Phone" required></div><div class="col-12"><input class="form-control" name="address_line1" placeholder="Address line 1" required></div><div class="col-12"><input class="form-control" name="address_line2" placeholder="Address line 2"></div><div class="col-6"><input class="form-control" name="city" placeholder="City" required></div><div class="col-6"><input class="form-control" name="state" placeholder="State" required></div><div class="col-6"><input class="form-control" name="postal_code" placeholder="PIN code" required></div><div class="col-6"><input class="form-control" name="label" placeholder="Label"></div><div class="col-12"><div class="form-check"><input class="form-check-input" type="checkbox" name="is_default" value="1" id="is_default"><label class="form-check-label" for="is_default">Make default</label></div></div></div></div><div class="card-footer text-end"><button class="btn btn-primary" type="submit">Save Address</button></div></form></div>
	<div class="col-lg-7"><div class="row g-3"><?php if (empty($addresses)): ?><div class="col-12"><?php echo empty_state('No addresses yet', 'Add a delivery address to speed up checkout.', 'fa-location-dot'); ?></div><?php else: foreach ($addresses as $address): ?><div class="col-md-6"><div class="card h-100"><div class="card-body"><div class="d-flex justify-content-between"><strong><?php echo html_escape($address->label ?: 'Address'); ?></strong><?php echo $address->is_default ? '<span class="badge badge-soft badge-soft-success">Default</span>' : ''; ?></div><p class="mb-2 small text-muted"><?php echo html_escape($address->first_name.' '.$address->last_name); ?><br><?php echo html_escape($address->address_line1); ?><br><?php echo html_escape($address->city.', '.$address->state.' '.$address->postal_code); ?><br><?php echo html_escape($address->phone); ?></p><a class="btn btn-sm btn-outline-danger" href="<?php echo site_url('account/addresses/delete/'.$address->id); ?>" data-confirm="Remove this address?">Remove</a></div></div></div><?php endforeach; endif; ?></div></div>
